import '@/styles/forms.css'
import { Controller, DefaultValues, SubmitHandler, useForm } from "react-hook-form";
import ReactDatePicker from "react-datepicker";
import { IFormInput } from '@/types/types';


const Register = () => {
    const { register, handleSubmit, formState: { errors }, control } = useForm<IFormInput>();
    const router = useRouter()
    const onSubmit: SubmitHandler<IFormInput> = (data) => alert(JSON.stringify(data));
    return (
        <form onSubmit={handleSubmit(onSubmit)} className='register-form'>
            <div>
                <label>First Name: </label>
                <input {...register("firstName", { required: "First name is required." })} />
            </div>
            <p className='error-message'>{errors.firstName?.message}</p>
            <div>
                <label>Last Name: </label>
                <input {...register("lastName", { required: "Last name is required." })} />
            </div>
            <p className='error-message'>{errors.lastName?.message}</p>
            <div>
                <label>Nick Name: </label>
                <input {...register("nickName")} />
            </div>
            <div>
                <label htmlFor='email'>e-mail: </label>
                <input id='email' type='email'  {...register("email", {
                    pattern: {
                        value: /^[^\s@]+@[^\s@]+\.[^\s@]+$/,
                        message: 'Please enter a valid email address (e.g., user@example.com).'
                    }
                })} />
            </div>
            <p className='error-message'>{errors.email?.message}</p>
            <div>
                <label htmlFor='password'>Password: </label>
                <input id='password' type='password' minLength={6} {...register("password", { required: "Password is required." })} />
            </div>
            <p className='error-message'>{errors.password?.message}</p>
            <div>
                <label htmlFor='dateOfBirth'>Date of Birth: </label>
                <input id='dateOfBirth' {...register("dateOfBirth")} />
                {/* <Controller<IFormInput>
                    control={control}
                    name="ReactDatepicker"
                    render={({ field: { value, ...fieldProps } }) => {
                        return (
                            <ReactDatePicker
                                {...fieldProps}
                                className="input"
                                placeholderText="Select date"
                                selected={value}
                            />
                        );
                    }}
                /> */}
            </div>
            <div>
                <label htmlFor='gender'>Gender: </label>
                <select id='gender '{...register("gender", { required: "Gender is required." })}>
                    <option value="female">female</option>
                    <option value="male">male</option>
                    <option value="other">other</option>
                </select>
            </div>
            <p className='error-message'>{errors.gender?.message}</p>
            <div>
                <label htmlFor='mobile'>Mobile: </label>
                <input id='mobile' {...register("mobile", { pattern: { value: /^\+?[0-9]{7,15}$/, message: "Please enter a valid mobile number." } })} />
            </div>
            <p className='error-message'>{errors.mobile?.message}</p>
            <div>
                <label>Address: </label>
                <input {...register("address")} />
            </div>
            <button>Submit</button>
            <p >Have an account? <a href="#" onClick={() => { router.push('/register') }}>Register</a></p>
        </form>
    );
};


export default Register;